    "名称": "江景天玺 (Jiangjing Tianxi)",
    "定位与概念": "位于临海市金融区核心地段，毗邻滨江公园的一线江景超豪华服务式公寓。其设计理念并非张扬的炫耀，而是为真正的顶层人士提供绝对的私密、安全与便捷，是一个闹市中的“垂直城堡”。",
    "公共设施与配套": {
      "大堂与安保": "采用酒店式环岛门廊设计，配备24小时的礼宾司与安保团队。访客需由业主确认，并通过独立的访客通道进入。电梯采用虹膜识别技术，部分高速电梯可直达高层特定区域，确保住户间的隐私。",
      "会所与社交": "位于大厦的第30层，设有【天玺会】，为业主专用。内部包含：一个可俯瞰江景的行政酒廊、数间可预约用于私人宴请的包厢、一个配备顶级音响设备的私人影院、以及一个专业的恒温恒湿雪茄房。",
      "健康与运动": "位于大厦的第5至6层。包含：一个25米长的室内恒温无边际泳池、一个配备全套进口器械并有常驻私教的健身房、独立的瑜伽与普拉提室、以及桑拿与蒸汽浴室。",
      "户外与景观": "大厦顶层（非复式住户区域）设有一个不对外开放的空中花园，配备烧烤区和小型吧台。裙楼部分有一个日式枯山水庭院，供住户散步。",
      "配套服务": "提供24小时管家服务、代客泊车、快递与外卖送至户门口、以及可预约的钟点工与私人厨师服务。"
    },
    "住户楼层分布": {
      "总楼层": "50层",
      "陆家 (温芷, 陆泽远, 林秀仪, 陆晴)": {
        "楼层": "49-50层",
        "描述": "位于大厦最顶层的复式空中别墅（Penthouse），拥有独立的私人电梯厅和超大空中露台，可以将临海市的江景与城市天际线尽收眼底。"
      },
      "{{user}}": {
        "楼层": "28层",
        "描述": "位于大厦的中高楼层，是一套拥有极佳视野的江景大平层公寓。与陆家乘坐的是同一区域的高速电梯，为他们之间的日常相遇提供了极高的可能性。"
      }
    }
  }
}

